package com.stockflow.document.application;
import com.stockflow.document.domain.*; import com.stockflow.shared.config.MindeeProperties; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Clock; import java.time.Instant; import java.util.UUID;
@Service class FinancialExtractionDraftLifecycle {
 private final DocumentRepository documents;private final FinancialExtractionDraftRepository drafts;private final DocumentActorAuthorizer authorizer;private final MindeeProperties config;private final Clock clock;
 FinancialExtractionDraftLifecycle(DocumentRepository d,FinancialExtractionDraftRepository r,DocumentActorAuthorizer a,MindeeProperties c,Clock k){documents=d;drafts=r;authorizer=a;config=c;clock=k;}
 @Transactional Document start(UUID actor,UUID id,UUID model){Document d=documents.lockActiveById(id).orElseThrow(DocumentNotFoundException::new);authorizer.requireOwnerOrAdmin(actor,d);if(!"application/pdf".equalsIgnoreCase(d.mediaType())&&!"image/jpeg".equalsIgnoreCase(d.mediaType())&&!"image/png".equalsIgnoreCase(d.mediaType()))throw new UnsupportedFinancialDocumentException();if(!config.configured())throw new MindeeConfigurationException();var old=drafts.lockByDocumentId(id);if(old.isPresent()&&old.get().processingStatus()==FinancialExtractionProcessingStatus.PROCESSING)throw new FinancialExtractionInProgressException();var next=old.orElseGet(()->FinancialExtractionDraft.start(UUID.randomUUID(),id,FinancialExtractionProvider.MINDEE_V2,model,Instant.now(clock)));if(old.isPresent())next.restart(FinancialExtractionProvider.MINDEE_V2,model,Instant.now(clock));drafts.save(next);return d;}
 @Transactional FinancialExtractionDraft finish(UUID id,FinancialDocumentExtractionPort.ExtractionResult v,FinancialExtractionProcessingStatus state){var d=drafts.lockByDocumentId(id).orElseThrow(FinancialExtractionNotFoundException::new);if(d.processingStatus()!=FinancialExtractionProcessingStatus.PROCESSING)throw new FinancialExtractionInProgressException();if(state==FinancialExtractionProcessingStatus.EXTRACTED)d.complete(v.supplierName().orElse(null),v.invoiceNumber().orElse(null),v.invoiceDate().orElse(null),v.currency().orElse(null),v.totalAmount().orElse(null),Instant.now(clock));else d.fail(state,Instant.now(clock));drafts.save(d);return d;}
}
